if [ -n "$NSEPA_PROBES" ]; then
    status CHECK 'HTTP access logs contain nsepa.deb requests answered with HTTP 206 and a one-byte response. Public reporting associates this with reconnaissance/probing; it does not establish exploitation. Review source, timestamps, and adjacent requests:'
    printf '%s\n' "$NSEPA_PROBES"
elif [ "$RECON_LOGS_FOUND" -eq 0 ]; then
    status CHECK 'No readable candidate HTTP logs found for the nsepa.deb one-byte probe check; coverage is unavailable.'
else
    status OK 'No nsepa.deb HTTP 206 one-byte probe pattern found in available access logs. This is limited to retained logs and the selected format.'
fi
if [ -n "$VP_PROBE_HITS" ]; then
    status CHECK 'The public-research marker vp_probe_nonexist occurs in retained HTTP access/error logs. Treat it as a reconnaissance lead, not a compromise indicator; correlate source and timestamp with other activity:'
    printf '%s\n' "$VP_PROBE_HITS"
elif [ "$RECON_LOGS_FOUND" -eq 0 ]; then
    status CHECK 'No readable candidate HTTP logs found for the vp_probe_nonexist check; coverage is unavailable.'
else
    status OK 'No vp_probe_nonexist marker found in available HTTP access/error logs. This is limited to retained logs and the selected format.'
fi

subsection 'Evidence coverage: retained log timestamps and approved file baseline' 'DEYDA-0048'
if command -v perl >/dev/null 2>&1; then
perl - "$CURRENT_INPUT" <<'DEYDA_COVERAGE_PERL'
use strict;
use warnings;
use JSON::PP;
use Digest::SHA;
use File::Find;
use POSIX qw(strftime);
use Time::Local qw(timelocal);

sub cached_digest {
    my ($path,$write_cache)=@_;
    my @before=stat($path);return undef unless @before && -f $path;
    my $signature=join(':',@before[0,1,7,9,10]);
    my $dir=$ENV{DEYDA_HASH_CACHE_DIR};
    my $key=Digest::SHA::sha256_hex($path);
    my $cache=defined($dir) && -d $dir ? "$dir/$key":undef;
    if ($cache && open(my $cf,'<',$cache)) {
        my $line=<$cf>;close $cf;
        if (defined($line) && $line =~ /^([0-9:]+) ([a-f0-9]{64})$/ && $1 eq $signature) {return $2;}
    }
    open my $fh,'<',$path or return undef;binmode $fh;
    my @opened=stat($fh);
    if (!@opened || $opened[0]!=$before[0] || $opened[1]!=$before[1]) {close $fh;return undef;}
    my $hash=eval {Digest::SHA->new(256)->addfile($fh)->hexdigest};
    my @after=stat($fh);close $fh;
    return undef unless defined($hash) && @after && join(':',@after[0,1,7,9,10]) eq $signature;
    # Reuse small existing caches; do not create 37660 cache files for the tree scan.
    if ($cache && ($write_cache || -f $cache) && open(my $cf,'>',$cache)) {print $cf "$signature $hash";close $cf;}
    return $hash;
}

my $build=shift;
sub finding { print "\n[$_[0]] $_[1]\n"; }
my $year=(localtime)[5]+1900;
$SIG{ALRM}=sub {finding('CHECK','UNKNOWN: coverage/file-baseline scan exceeded 60 seconds; partial results only.');exit;};
alarm 60;
my %months=map { (qw(Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec))[$_]=>$_ } 0..11;
my @logs=grep {-f $_} map {glob($_)} qw(/var/log/ns.log* /var/log/messages* /var/log/httpaccess* /var/log/auth.log* /var/log/notice.log*);
my ($unreadable,$limited,$total,$unparsed)=(0,0,0,0);
for my $path (@logs) {
    my $fh;
    if ($path =~ /\.gz$/) {open($fh,'-|','gzip','-cd','--',$path) or do {$unreadable++;next};}
    else {open($fh,'<',$path) or do {$unreadable++;next};}
    my ($min,$max,$count,$lines,$unknown)=(undef,undef,0,0,0);
    my $bytes=0;
    while (my $l=<$fh>) {
        if (++$lines>200000 || ($bytes+=length($l))>64*1024*1024) {$limited++;last;}
        my $epoch;
        if ($l =~ /\b(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d):(\d\d)(Z|[+-]\d\d:?\d\d)?/) {
            my ($y,$m,$d,$h,$mi,$se,$tz)=($1,$2,$3,$4,$5,$6,$7);
            $epoch=eval {$tz ? Time::Local::timegm($se,$mi,$h,$d,$m-1,$y):timelocal($se,$mi,$h,$d,$m-1,$y)};
            if (defined($epoch) && defined($tz) && $tz ne 'Z') {my ($sign,$hh,$mm)=$tz =~ /^([+-])(\d\d):?(\d\d)$/;$epoch-=($sign eq '+'?1:-1)*($hh*3600+$mm*60);}
        } elsif ($l =~ /^([A-Z][a-z]{2})\s+(\d{1,2})\s+(\d\d):(\d\d):(\d\d)/ && exists $months{$1}) {
            my ($mo,$d,$h,$mi,$se)=($months{$1},$2,$3,$4,$5);
            $epoch=eval {timelocal($se,$mi,$h,$d,$mo,$year)};
            $epoch=eval {timelocal($se,$mi,$h,$d,$mo,$year-1)} if defined($epoch) && $epoch>time()+86400;
        } elsif ($l =~ m{\[(\d{1,2})/([A-Z][a-z]{2})/(\d{4}):(\d\d):(\d\d):(\d\d) ([+-])(\d\d)(\d\d)\]} && exists $months{$2}) {
            my ($d,$mo,$y,$h,$mi,$se,$sign,$hh,$mm)=($1,$months{$2},$3,$4,$5,$6,$7,$8,$9);
            $epoch=eval {Time::Local::timegm($se,$mi,$h,$d,$mo,$y)};
            $epoch-=($sign eq '+'?1:-1)*($hh*3600+$mm*60) if defined $epoch;
        }
        if (defined $epoch) {$min=$epoch if !defined($min)||$epoch<$min;$max=$epoch if !defined($max)||$epoch>$max;$count++;}
        else {$unknown++;}
    }
    my $closed=close $fh; $unreadable++ unless $closed || $lines>200000;
    $total+=$count; $unparsed+=$unknown;
    my $safe=$path; $safe =~ s/[^A-Za-z0-9_.\/-]/?/g;
    if ($count) {printf "%s: parsed=%d, unknown-lines=%d, earliest=%s, latest=%s (UTC)\n",$safe,$count,$unknown,strftime('%Y-%m-%dT%H:%M:%SZ',gmtime($min)),strftime('%Y-%m-%dT%H:%M:%SZ',gmtime($max));}
    else {finding('CHECK',"$safe: UNKNOWN timestamp coverage.");}
}
finding('CHECK',"Log coverage: files=".scalar(@logs).", parsed timestamps=$total, unknown lines=$unparsed, unreadable/decompression errors=$unreadable, capped files=$limited. Syslog year is inferred from current time; timezone-less records use appliance timezone. Earliest/latest timestamps do not prove continuity or exclude deleted logs.");
finding('CHECK','UNKNOWN: no selected retained logs found.') unless @logs;
my $manifest_path=$ENV{DEYDA_FILE_BASELINE};
my $manifest;
my $internal_json=<<'DEYDA_INTERNAL_1417346';
